/* Interactive map; geographic hazard layers retain their provider legends. */
window.FloodExplorer=(()=>{
  let map,options,config,lastState,pointLayer,pointRequest=0,basemapReady=false,imageryLayer,imageryMode='reference',pendingTerrain=null;
  const markers=[],layers={},layerState={},reportMarkers=[];
  const colors={Lower:'#23845c',Watch:'#d3a422',Elevated:'#e37928',High:'#c3353b',Unavailable:'#8b939d'};
  const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const el=id=>document.getElementById(id);
  function loadBasemap(){const data=window.REGIONAL_BASEMAP;if(!data?.countries?.features?.length){el('basemap-status').textContent='Regional basemap unavailable. City positions and source hazard layers remain selectable.';return;}map.createPane('geographyPane');map.getPane('geographyPane').style.zIndex=210;map.createPane('riverReferencePane');map.getPane('riverReferencePane').style.zIndex=300;L.geoJSON(data.countries,{pane:'geographyPane',interactive:false,style:f=>({color:'#98acc6',weight:1,fillColor:['Somalia','Somaliland'].includes(f.properties?.ADMIN)?'#e6eef9':'#f2f5fa',fillOpacity:1}),attribution:'Made with <a href="https://www.naturalearthdata.com/">Natural Earth</a> (public domain)'}).addTo(map);if(data.rivers?.features?.length)L.geoJSON(data.rivers,{pane:'riverReferencePane',interactive:false,style:{color:'#6dabbc',weight:1.8,opacity:.85}}).addTo(map);basemapReady=true;el('basemap-status').textContent='Natural Earth regional reference map · coastlines, boundaries and rivers. Generalized geography; no street-level detail. Blue river lines are not current floodwater.';L.control?.scale?.({imperial:false})?.addTo(map);}
  async function readConfig(){if(window.HAZARD_SOURCES)return window.HAZARD_SOURCES;const r=await fetch('hazard-sources.json',{cache:'no-store'});if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json()}
  function setBasemap(value){if(!map)return;imageryMode=value==='satellite'?'satellite':'reference';if(el('basemap-select'))el('basemap-select').value=imageryMode;if(imageryMode==='reference'){if(imageryLayer)map.removeLayer(imageryLayer);if(el('map-imagery-status'))el('map-imagery-status').textContent='Regional reference geography · no satellite basemap requested.';return}if(!imageryLayer){map.createPane('imageryPane');map.getPane('imageryPane').style.zIndex=220;imageryLayer=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{pane:'imageryPane',maxNativeZoom:18,maxZoom:18,attribution:'Imagery © Esri, Maxar, Earthstar Geographics, GIS User Community'});imageryLayer.on('loading',()=>{if(imageryMode==='satellite'&&el('map-imagery-status'))el('map-imagery-status').textContent='Loading satellite basemap…'});imageryLayer.on('load',()=>{if(imageryMode==='satellite'&&el('map-imagery-status'))el('map-imagery-status').textContent='Esri World Imagery · imagery dates vary by location; this is background context, not current flooding.'});imageryLayer.on('tileerror',()=>{if(imageryMode==='satellite'){setBasemap('reference');if(el('map-imagery-status'))el('map-imagery-status').textContent='Satellite basemap unavailable. Regional reference map restored.'}})}imageryLayer.addTo(map);}
  function communityReports(records=[]){reportMarkers.forEach(m=>map?.removeLayer(m));reportMarkers.length=0;if(!map)return;for(const r of records){if(!Number.isFinite(r.latitude)||!Number.isFinite(r.longitude)||r.latitude<-2||r.latitude>13||r.longitude<40||r.longitude>52)continue;const city=options.cities.find(c=>c[0].toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')===r.cityId);const m=L.circleMarker([r.latitude,r.longitude],{radius:6,color:'#fff',weight:2,fillColor:'#8850be',fillOpacity:1,pane:'markerPane'}).bindPopup(`<b>Community ${escape(r.category)} report · unverified</b><p>${escape(city?.[0]||r.cityId)} · observed ${escape(r.observedAt)}<br><span data-i18n-skip lang="und">${escape(r.description)}</span></p><a href="#community-report-${escape(r.id)}">Photos, impact details &amp; comments ↓</a><p><small>A reported location is not a mapped flood boundary.</small></p>`);reportMarkers.push(m);if(el('layer-community')?.checked!==false)m.addTo(map)}}
  function showStatus(){if(!config)return;const active=Object.keys(layers).filter(k=>el('layer-'+k).checked);el('map-status').textContent=active.length?active.map(k=>`${config.layers[k].title}: ${layerState[k]||'connecting'}`).join(' · '):'Geographic overlays hidden. City colors show the selected-day screening priority.';window.FloodTerrain?.setSource(config,{active:active.includes('susceptibility'),susceptibility:layerState.susceptibility,history:layerState.history});}
  function showLegend(){if(!config)return;el('map-legend').innerHTML=Object.entries(config.layers).filter(([k])=>el('layer-'+k)?.checked).map(([k,v])=>`<div class="layer-legend"><b>${escape(v.title)}</b><span>${escape(v.dateLabel||'Source date not supplied')}</span><p>${escape(v.description||'')}</p>${v.legendUrl?`<img src="${escape(v.legendUrl)}" alt="Official ${escape(v.title)} color legend">`:''}<a target="_blank" rel="noopener" href="${escape(v.sourceUrl)}">Source & methodology ↗</a></div>`).join('');}
  async function init(opts){options=opts;window.FloodTerrain?.init({cities:options.cities,onSelectCity:options.onSelectCity,onFocus:showTerrain,onInspect:i=>{const c=options.cities[i];if(c)inspect(c[2],c[3],{sampleKind:'city-center',cityIndex:i});}});if(!window.L){el('map').innerHTML='<p class="map-fallback">The map library could not load. City selection and forecasts remain available below.</p>';el('map-status').textContent='Interactive map unavailable.';window.FloodTerrain?.setSource(null,{error:'Interactive map unavailable'});return;}
    map=L.map('map',{scrollWheelZoom:false,maxZoom:18,minZoom:5,maxBounds:[[ -5,35],[18,54]],maxBoundsViscosity:.65}).setView([6.5,46.5],6);loadBasemap();
    map.createPane('hazardPane');map.getPane('hazardPane').style.zIndex=350;
    options.cities.forEach((c,i)=>{const marker=L.circleMarker([c[2],c[3]],{radius:7,color:'#fff',weight:2,fillColor:colors.Unavailable,fillOpacity:1}).addTo(map).bindTooltip(c[0],{direction:'top'});marker.on('click',()=>options.onSelectCity(i));markers.push(marker)});
    map.on('click',e=>inspect(e.latlng.lat,e.latlng.lng));el('map-overview').onclick=overview;
    if(el('basemap-select'))el('basemap-select').onchange=e=>setBasemap(e.target.value);
    if(el('layer-community'))el('layer-community').onchange=()=>reportMarkers.forEach(m=>el('layer-community').checked?m.addTo(map):map.removeLayer(m));
    for(const key of ['susceptibility','history','breakages','breakagesJuba']){const checkbox=el('layer-'+key);if(!checkbox)continue;checkbox.disabled=true;checkbox.onchange=()=>{if(!layers[key])return;checkbox.checked?layers[key].addTo(map):map.removeLayer(layers[key]);showLegend();showStatus();}};
    overview();window.ObservedFlood?.init({map,cities:options.cities});try{config=await readConfig();if(!config.wmsUrl||!config.layers)throw Error('Invalid geographic source configuration');for(const[key,v]of Object.entries(config.layers)){if(!el('layer-'+key))continue;const layer=L.tileLayer.wms(config.wmsUrl,{layers:v.name,format:'image/png',transparent:true,version:'1.1.1',styles:v.style||'',...(v.cqlFilter?{cql_filter:v.cqlFilter}:{}),opacity:key==='susceptibility'?.58:.8,pane:'hazardPane',attribution:'Hazard layers: FAO SWALIM',maxZoom:18});layer.on('loading',()=>{layerState[key]='loading tiles';showStatus()});layer.on('load',()=>{if(layerState[key]!=='some tiles unavailable')layerState[key]='source tiles loaded';showStatus()});layer.on('tileerror',()=>{layerState[key]='some tiles unavailable';showStatus()});layers[key]=layer;el('layer-'+key).disabled=false;if(el('layer-'+key).checked)layer.addTo(map)}showLegend();showStatus();if(pendingTerrain!==null)showTerrain(pendingTerrain);}catch(e){el('map-status').textContent='SWALIM geographic layers unavailable: '+e.message;window.FloodTerrain?.setSource(null,{error:e.message});}if(lastState)update(lastState);
  }
  function update(state){lastState=state;const city=options?.cities[state.cityIndex];if(!city)return;window.FloodTerrain?.updateCity(state.cityIndex);el('citynav').innerHTML=options.cities.map((c,i)=>{const s=state.cityStates?.[i]||{code:'Unavailable',label:'Unavailable'};return `<button class="city-choice ${i===state.cityIndex?'selected':''}" data-city="${i}" aria-current="${i===state.cityIndex?'true':'false'}"><span class="city-dot" style="background:${colors[s.code]||colors.Unavailable}"></span><span><b>${escape(c[0])}</b><small>${escape(s.label)}</small></span></button>`}).join('');markers.forEach((m,i)=>{const s=state.cityStates?.[i]||{code:'Unavailable',label:'Unavailable'};m.setStyle({fillColor:colors[s.code]||colors.Unavailable,radius:i===state.cityIndex?11:7,color:i===state.cityIndex?'#0c2d55':'#fff'});m.bindPopup(`<b>${escape(options.cities[i][0])}</b><p>${escape(state.selectedDate)} · ${escape(s.label)}<br>Forecast rain: ${typeof s.rainMm==='number'?s.rainMm.toFixed(1)+' mm':'unavailable'}${s.stationLabel?'<br>'+escape(s.stationLabel):''}</p><small>Screening priority, not a flood probability. Scenarios do not change these live source values.</small>`)});}
  let pendingView=null;const sized=()=>{if(!map)return false;const box=map.getContainer?.();return !box||(box.clientWidth>0&&box.clientHeight>0)};function focus(i){if(!map)return;const c=options.cities[i];if(!c)return;if(!sized()){pendingView=()=>map.setView([c[2],c[3]],11);return}pendingView=null;map.flyTo([c[2],c[3]],11,{duration:.65});}
  function showTerrain(i){const index=Number(i);if(!Number.isInteger(index)||!options?.cities[index])return;pendingTerrain=config?null:index;for(const key of ['susceptibility','history']){const checkbox=el('layer-'+key);if(checkbox)checkbox.checked=true;if(map&&layers[key])layers[key].addTo(map);}focus(index);el('map')?.scrollIntoView?.({behavior:'smooth',block:'center'});showLegend();showStatus();}
  function focusPoint(lat,lon){if(map&&Number.isFinite(lat)&&Number.isFinite(lon)){if(!sized()){pendingView=()=>map.setView([lat,lon],12);return}pendingView=null;map.flyTo([lat,lon],12,{duration:.65})}}
  function overview(){if(!map||!options)return;const fit=()=>map.fitBounds(options.cities.map(c=>[c[2],c[3]]),{padding:[25,25]});if(!sized()){pendingView=fit;return}pendingView=null;fit();}
  async function inspect(lat,lon,metadata={}){
    options.onLocate?.({lat,lon});window.ObservedFlood?.inspect(lat,lon);
    const request=++pointRequest;
    window.FloodTerrain?.loading(lat,lon,metadata);
    el('point-info').textContent=`Checking ${lat.toFixed(5)}, ${lon.toFixed(5)}…`;
    if(pointLayer)map?.removeLayer(pointLayer);
    if(map)pointLayer=L.circleMarker([lat,lon],{radius:6,weight:2,color:'#15355d',fillColor:'#fff',fillOpacity:1}).addTo(map);
    try{
      let data;
      if(/^https?:$/.test(location.protocol)){
        const r=await fetch(`/api/hazard-point?lat=${lat}&lon=${lon}`,{signal:AbortSignal.timeout(25000),cache:'no-store'});
        if(!r.ok)throw Error(`HTTP ${r.status}`);data=await r.json();
      }else{
        const r=await fetch(`https://api.open-meteo.com/v1/elevation?latitude=${lat}&longitude=${lon}`,{signal:AbortSignal.timeout(25000)});
        if(!r.ok)throw Error(`HTTP ${r.status}`);const d=await r.json();
        data={lat,lon,elevationM:d.elevation?.[0],errors:['Start the local server to query SWALIM hazard classes.']};
      }
      if(request!==pointRequest)return;
      const label=data.susceptibility?.label||'Class unavailable';
      el('point-info').innerHTML=`<b>Selected point · ${lat.toFixed(5)}, ${lon.toFixed(5)}</b><p>Elevation: ${typeof data.elevationM==='number'?data.elevationM.toFixed(1)+' m above sea level':'unavailable'} · SWALIM susceptibility: ${escape(label)}<br>Historical flood-prone layer: ${data.historical?.intersects===true?'intersects mapped historical area':data.historical?.intersects===false?'no feature returned at this point; flooding is still possible':'query unavailable'}</p><small>${escape(data.sourceNote||'Elevation alone cannot establish flood risk or a water-diversion route.')}</small>${data.errors?.length?'<p class="note">'+escape(data.errors.join(' · '))+'</p>':''}`;
      if(data.breakages?.length){
        el('point-info').innerHTML+='<h3>Nearby bank assessment records</h3>'+data.breakages.map(b=>'<p><b>'+escape(b.river)+' · '+escape(b.status)+'</b><br>Imagery date: '+escape(b.imageryDate)+' · '+escape(b.assessment)+'<br><a target='+String.fromCharCode(34)+'_blank'+String.fromCharCode(34)+' rel='+String.fromCharCode(34)+'noopener'+String.fromCharCode(34)+' href='+String.fromCharCode(34)+escape(b.sourceUrl)+String.fromCharCode(34)+'>Source assessment ↗</a></p>').join('')+'<small>Nearby imagery records need field verification; current repair status is unknown.</small>';
      }
      window.FloodTerrain?.point({...data,lat,lon,...metadata});
      options.onPoint?.({...data,terrainClass:label});
    }catch(e){
      if(request!==pointRequest)return;
      el('point-info').textContent=`Location query unavailable: ${e.message}. No terrain class is inferred.`;
      window.FloodTerrain?.point({lat,lon,...metadata,elevationM:null,susceptibility:{value:null,label:'Query unavailable'},historical:{intersects:null},errors:['Location query unavailable: '+e.message]});
      options.onPoint?.({lat,lon,elevationM:null,terrainClass:'Unavailable'});
    }
  }
  function clearPoint(){pointRequest++;if(pointLayer)map?.removeLayer(pointLayer);pointLayer=null;el('point-info').textContent='Click a map point to inspect its elevation and mapped flood susceptibility.';window.FloodTerrain?.clearPoint();}
  function getState(){return{cityIndex:lastState?.cityIndex,selectedDate:lastState?.selectedDate,scenario:lastState?.scenario,config,basemap:{mode:imageryMode==='satellite'?'satellite-context':'regional-reference',ready:basemapReady},communityPins:reportMarkers.length,activeLayers:Object.keys(layers).filter(k=>el('layer-'+k).checked),layerState:{...layerState}};}
  return{init,update,focus,focusPoint,overview,inspect,clearPoint,getState,setBasemap,communityReports,showTerrain,resize:()=>{if(!map)return;map.invalidateSize({animate:false});if(pendingView&&sized()){const view=pendingView;pendingView=null;view()}}};
})();




